WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_eng_m_complex'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '复杂综合应用', 'kp-eng-m-complex', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "复杂工程综合应用"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "融合了费用计算、最值统筹、多段突变的地狱级压轴题。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "篇幅极长，包含了效率变化、中途停工、外援加入，最后还要算工钱或寻找最优解。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心战法：表格剥离法"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "放弃大脑心算，拿出一张草稿纸，画出标准的【阶段追踪表】。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[画出四列表格: 阶段、在场人员、当前效率、持续时间] --> B[逐句翻译题干, 把每一个阶段的数据填入表格]\nB --> C[在表的最右侧新增一列: 本阶段产出工作量]\nC --> D[将所有阶段的产出相加, 必须等于赋予的总工程量 W]\nD --> E[如果要求费用, 再增加一列: 本阶段消耗资金]\nE --> F[根据未知数的不同, 解最终的统筹或费用方程]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "企图一步登天列出终极长式子：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "不要试图用一个长达一整行的算式解决问题，少一个括号全盘皆输。模块化、表格化才是解长题的终极工程学思维。"}]}]}]}$$ AS jsonb), NULL, '复杂综合应用的核心考点与实战推导。', category_node.id, CAST('["数量关系", "工程问题", "复杂综合应用"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eng_m_complex", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
